<script>
  const stage = document.getElementById('stage');
  const slides = Array.from(document.querySelectorAll('.slide'));
  let current = 0;

  function fit() {
    const scale = Math.min(window.innerWidth / 1920, window.innerHeight / 1080);
    const x = (window.innerWidth - 1920 * scale) / 2;
    const y = (window.innerHeight - 1080 * scale) / 2;
    stage.style.transform = `translate(${x}px, ${y}px) scale(${scale})`;
  }

  function show(index) {
    current = Math.max(0, Math.min(slides.length - 1, index));
    slides.forEach((s, i) => s.classList.toggle('is-active', i === current));
  }

  document.addEventListener('keydown', (e) => {
    if (['ArrowRight', 'ArrowDown', 'PageDown', ' '].includes(e.key)) show(current + 1);
    if (['ArrowLeft', 'ArrowUp', 'PageUp'].includes(e.key)) show(current - 1);
  });

  document.addEventListener('click', (e) => {
    show(e.clientX > window.innerWidth / 2 ? current + 1 : current - 1);
  });

  window.addEventListener('resize', fit);
  fit();
</script>
